 28→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
 29→// then applies any overrides from .entire/settings.local.json if it exists.
 30→// Returns default settings if neither file exists.
 31→// Works correctly from any subdirectory within the repository.
 32→func LoadEntireSettings(ctx context.Context) (*settings.EntireSettings, error) {
 33→	s, err := settings.Load(ctx)
 34→	if err != nil {
 35→		return nil, fmt.Errorf("loading settings: %w", err)
 36→	}
 37→	return s, nil
 38→}
