100→// JoinAgentNames joins agent names into a comma-separated string.
101→func JoinAgentNames(names []types.AgentName) string {
102→	strs := make([]string, len(names))
103→	for i, n := range names {
104→		strs[i] = string(n)
105→	}
106→	return strings.Join(strs, ",")
107→}
