 96→// runSetupFlow runs the first-time setup flow (agent selection + hooks + settings).
 97→// Shared by root command (no args), `entire configure`, and `entire enable` on fresh repos.
 98→func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
 99→	// Discover external agent plugins so they appear in agent selection.
100→	// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
101→	// during setup the setting doesn't exist yet.
102→	external.DiscoverAndRegisterAlways(ctx)
103→
104→	agents, err := detectOrSelectAgent(ctx, w, nil)
105→	if err != nil {
106→		return fmt.Errorf("agent selection failed: %w", err)
107→	}
108→
109→	return runEnableInteractive(ctx, w, agents, opts)
110→}
