112→// runAddAgents shows which agents are currently enabled and lets the user add more.
113→// Already-installed agents cannot be deselected.
114→func runAddAgents(ctx context.Context, w io.Writer, opts EnableOptions) error {
115→	installedNames := GetAgentsWithHooksInstalled(ctx)
116→
117→	// Show currently installed agents
118→	if len(installedNames) > 0 {
119→		displayNames := make([]string, 0, len(installedNames))
120→		for _, name := range installedNames {
121→			if ag, err := agent.Get(name); err == nil {
122→				displayNames = append(displayNames, string(ag.Type()))
123→			}
124→		}
125→		fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
126→	}
127→
128→	// Build pre-selection set from installed agents
129→	installedSet := make(map[types.AgentName]struct{}, len(installedNames))
130→	for _, name := range installedNames {
131→		installedSet[name] = struct{}{}
132→	}
133→
134→	// Check if we can prompt interactively
135→	if !canPromptInteractively() {
136→		fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
137→		fmt.Fprintln(w, "Use: entire configure --agent <name>")
138→		return nil
139→	}
140→
141→	// Discover external agent plugins after the interactivity check to avoid
142→	// scanning PATH (with a 10s timeout) in non-interactive contexts.
143→	// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
144→	// during setup the setting doesn't exist yet.
145→	external.DiscoverAndRegisterAlways(ctx)
146→
147→	// Build options from registered agents
148→	agentNames := agent.List()
149→	options := make([]huh.Option[string], 0, len(agentNames))
150→	for _, name := range agentNames {
151→		ag, err := agent.Get(name)
152→		if err != nil {
153→			continue
154→		}
155→		if _, ok := agent.AsHookSupport(ag); !ok {
156→			continue
157→		}
158→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
159→			continue
160→		}
161→		opt := huh.NewOption(string(ag.Type()), string(name))
162→		if _, installed := installedSet[name]; installed {
163→			opt = opt.Selected(true)
164→		}
165→		options = append(options, opt)
166→	}
167→
168→	if len(options) == 0 {
169→		return errors.New("no agents with hook support available")
170→	}
171→
172→	// Check if all agents are already installed
173→	allInstalled := true
174→	for _, name := range agentNames {
175→		ag, err := agent.Get(name)
176→		if err != nil {
177→			continue
178→		}
179→		if _, ok := agent.AsHookSupport(ag); !ok {
180→			continue
181→		}
182→		if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
183→			continue
184→		}
185→		if _, installed := installedSet[name]; !installed {
186→			allInstalled = false
187→			break
188→		}
189→	}
190→	if allInstalled {
191→		fmt.Fprintln(w, "All available agents are already enabled.")
192→		return nil
193→	}
194→
195→	var selectedAgentNames []string
196→	form := NewAccessibleForm(
197→		huh.NewGroup(
198→			huh.NewMultiSelect[string]().
199→				Title("Enable more agents").
200→				Description("Use space to select, enter to confirm.").
201→				Options(options...).
202→				Validate(func(selected []string) error {
203→					if len(selected) == 0 {
204→						return errors.New("please select at least one agent")
205→					}
206→					// Ensure previously installed agents are still selected
207→					selectedSet := make(map[string]struct{}, len(selected))
208→					for _, s := range selected {
209→						selectedSet[s] = struct{}{}
210→					}
211→					for _, name := range installedNames {
212→						if _, ok := selectedSet[string(name)]; !ok {
213→							ag, err := agent.Get(name)
214→							if err != nil {
215→								continue
216→							}
217→							return fmt.Errorf("cannot remove %s — use `entire configure --remove %s` to remove it", ag.Type(), name)
218→						}
219→					}
220→					return nil
221→				}).
222→				Value(&selectedAgentNames),
223→		),
224→	)
225→	if err := form.Run(); err != nil {
226→		return fmt.Errorf("agent selection cancelled: %w", err)
227→	}
228→
229→	// Find newly selected agents (not previously installed)
230→	var newAgents []agent.Agent
231→	for _, name := range selectedAgentNames {
232→		if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
233→			continue
234→		}
235→		ag, err := agent.Get(types.AgentName(name))
236→		if err != nil {
237→			return fmt.Errorf("failed to get agent %s: %w", name, err)
238→		}
239→		newAgents = append(newAgents, ag)
240→	}
241→
242→	if len(newAgents) == 0 {
243→		fmt.Fprintln(w, "No new agents selected.")
244→		return nil
245→	}
246→
247→	// Install hooks for newly selected agents only
248→	for _, ag := range newAgents {
249→		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
250→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
251→		}
252→	}
253→
254→	// Auto-enable external_agents setting if any new agent is external.
255→	for _, ag := range newAgents {
256→		if external.IsExternal(ag) {
257→			s, loadErr := LoadEntireSettings(ctx)
258→			if loadErr != nil {
259→				s = &EntireSettings{}
260→			}
261→			if !s.ExternalAgents {
262→				s.ExternalAgents = true
263→				var saveErr error
264→				if opts.UseLocalSettings {
265→					saveErr = SaveEntireSettingsLocal(ctx, s)
266→				} else {
267→					saveErr = SaveEntireSettings(ctx, s)
268→				}
269→				if saveErr != nil {
270→					return fmt.Errorf("failed to save external_agents setting: %w", saveErr)
271→				}
272→			}
273→			break
274→		}
275→	}
276→
277→	newTypes := make([]string, 0, len(newAgents))
278→	for _, ag := range newAgents {
279→		newTypes = append(newTypes, string(ag.Type()))
280→	}
281→	fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(newTypes, ", "))
282→
283→	return nil
284→}
